import type { Card } from "@shared/cards";
import { memo, useEffect, useRef } from "react";
import { LinkedText } from "../cards/LinkedText";
import { HtmlCardBody } from "../cards/PrototypeBody";
import { RecordCard } from "../cards/RecordCard";
import { Firstmate } from "../character/Firstmate";
import { Button, CARD_STACK_WIDTH, CardStack, ResponseCard, VoiceInput } from "../design";
import type { CardKindContribution } from "../plugins/contributions";
import { useCardKind } from "../plugins/host";
import { stackEntries, type Theme, useShellStore } from "./store";
import { VoiceNotice } from "./VoiceNotice";

/**
 * The stage's fixed geometry is designed at the card stack's width; on a
 * narrow stage (the minimum window with both rails docked leaves 360px)
 * the card stack and the input follow the stage instead of overflowing
 * it. `cqw` is the stage's width: App.tsx makes the stage an inline-size
 * container for exactly this.
 */
const STAGE_WIDTH = `min(${CARD_STACK_WIDTH}px, calc(100cqw - 2 * var(--space-4)))`;

/**
 * The only subscriber to `cards` / `cardIndex` / `record`. Streaming body
 * updates reconcile this layer and leave the Firstmate / voice input
 * unmounted from that traffic. How a kind is dressed and how its body
 * renders is the `card-kind` registry's answer (docs/ui-plugins.md), not a
 * switch here: a streaming card wears the host's `working` chrome, then
 * its kind's own. The open task-record card (P4) is the stack's front
 * entry: a view the shell holds, rendered by RecordCard, never a persisted
 * card.
 */
function CardLayer() {
  const cards = useShellStore((s) => s.cards);
  const record = useShellStore((s) => s.record);
  const cardIndex = useShellStore((s) => s.cardIndex);
  const theme = useShellStore((s) => s.theme);
  const actOnCard = useShellStore((s) => s.actOnCard);
  const closeCard = useShellStore((s) => s.closeCard);
  const closeRecord = useShellStore((s) => s.closeRecord);
  const prevCard = useShellStore((s) => s.prevCard);
  const nextCard = useShellStore((s) => s.nextCard);

  const entries = stackEntries(cards, record);
  const index = Math.min(cardIndex, entries.length - 1);
  const entry = entries[index];
  const card = entry?.kind === "card" ? entry.card : undefined;
  const kind = useCardKind(card?.kind ?? "");
  if (!entry) return null;

  return (
    <div
      style={{
        position: "absolute",
        left: "50%",
        top: "calc(50% - 60px)",
        transform: "translate(-50%,-50%)",
        width: STAGE_WIDTH,
      }}
    >
      <CardStack
        index={index}
        count={entries.length}
        width="100%"
        onPrev={prevCard}
        onNext={nextCard}
      >
        {entry.kind === "record" ? (
          <RecordCard taskId={entry.taskId} theme={theme} onClose={closeRecord} />
        ) : (
          <StackedCard
            card={entry.card}
            chrome={kind.chrome}
            bodyPolicy={kind.body}
            theme={theme}
            onClose={() => closeCard(entry.card.id)}
            onAction={(actionId) => actOnCard(entry.card.id, actionId)}
          />
        )}
      </CardStack>
    </div>
  );
}

/** A persisted card in its kind's chrome, body in the sandboxed frame. */
function StackedCard({
  card,
  chrome,
  bodyPolicy,
  theme,
  onClose,
  onAction,
}: {
  card: Card;
  chrome: CardKindContribution["chrome"];
  bodyPolicy: CardKindContribution["body"];
  theme: Theme;
  onClose: () => void;
  onAction: (actionId: string) => void;
}) {
  const pending = useShellStore((s) => s.pendingCardActions[card.id]);
  const error = useShellStore((s) => s.cardActionErrors[card.id]);
  const streaming = card.status === "streaming";
  return (
    <ResponseCard
      kind={streaming ? "working" : chrome}
      title={card.title}
      meta={card.meta}
      width="100%"
      onClose={onClose}
      actions={
        card.actions.length > 0
          ? card.actions.map((action) => (
              <Button
                key={action.id}
                variant={action.variant ?? "secondary"}
                pending={pending?.actionId === action.id}
                disabled={Boolean(pending)}
                onClick={() => onAction(action.id)}
              >
                {action.label}
              </Button>
            ))
          : undefined
      }
    >
      {error && (
        <p role="alert" style={{ color: "var(--danger)", fontSize: "var(--text-sm)" }}>
          {error}
        </p>
      )}
      {streaming && bodyPolicy.streaming === "plain" ? (
        <LinkedText text={card.body} />
      ) : (
        <HtmlCardBody
          body={card.body}
          theme={theme}
          profile={bodyPolicy.profile}
          title={card.title}
          declaredActionIds={card.actions.map((action) => action.id)}
          onAction={onAction}
        />
      )}
    </ResponseCard>
  );
}

export const HomeScreen = memo(function HomeScreen() {
  const phase = useShellStore((s) => s.phase);
  const inputText = useShellStore((s) => s.inputText);
  const kick = useShellStore((s) => s.kick);
  const submitted = useShellStore((s) => s.submitted);
  const setInputText = useShellStore((s) => s.setInputText);
  const keystroke = useShellStore((s) => s.keystroke);
  const abandonRecording = useShellStore((s) => s.abandonRecording);
  const acceptRecording = useShellStore((s) => s.acceptRecording);
  const submit = useShellStore((s) => s.submit);
  const attachments = useShellStore((s) => s.attachments);
  const attachImages = useShellStore((s) => s.attachImages);
  const removeAttachment = useShellStore((s) => s.removeAttachment);
  const voiceSupported = useShellStore((s) => s.voiceSupported);
  const transcribing = useShellStore((s) => s.transcribing);
  const view = useShellStore((s) => s.view);
  const firstmateBusy = useShellStore((s) => s.firstmateBusy);
  const recording = phase === "recording";

  const focusRequest = useShellStore((s) => s.focusRequest);
  const inputRef = useRef<HTMLInputElement>(null);
  const focusHandled = useRef(0);
  useEffect(() => {
    // Each request is consumed exactly once, at the moment it fires: a
    // later view or recording change must not replay a stale focus steal
    // (e.g. refocusing the prompt on every return from Settings).
    if (focusRequest === focusHandled.current) return;
    focusHandled.current = focusRequest;
    if (view === "home" && !recording) {
      inputRef.current?.focus();
    }
  }, [focusRequest, view, recording]);

  const working = firstmateBusy;
  // Cards up is layout only; the character heats for Firstmate's own turn.
  const showCards = phase === "working";
  const typing = inputText.length > 0;
  const listening = phase === "recording" || typing;

  const screenLabel = showCards ? "Working" : listening ? "Listening" : "Null state";

  // Fixed vertical geometry: the Firstmate layer and card layer are
  // absolutely positioned; the input never moves.
  return (
    <div data-screen-label={screenLabel} style={{ position: "absolute", inset: 0 }}>
      {/* The Firstmate stays put in the back - cards float in front; when the
          stack empties he is revealed again. */}
      <div
        style={{
          position: "absolute",
          left: "50%",
          top: "calc(50% - 60px)",
          transform: "translate(-50%,-50%)",
          opacity: showCards ? 0.45 : 1,
          filter: showCards ? "blur(3px)" : "none",
          transition:
            "opacity var(--dur-slow) var(--ease-out),filter var(--dur-slow) var(--ease-out)",
        }}
      >
        <Firstmate
          listening={listening}
          busy={working}
          size={300}
          kick={kick}
          submitSignal={submitted}
        />
      </div>
      {showCards && <CardLayer />}
      <div
        style={{
          position: "absolute",
          left: "50%",
          // Anchored by the input's top (100% - 96px margin - 52px input), so
          // a voice notice growing underneath never shifts the input itself.
          top: "calc(100% - 148px)",
          transform: "translateX(-50%)",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          gap: 10,
        }}
      >
        <VoiceInput
          mode={phase === "recording" ? "recording" : "idle"}
          width={STAGE_WIDTH}
          value={inputText}
          keybindHint={
            transcribing
              ? "transcribing what you said"
              : voiceSupported === false
                ? "type a task for a crewmate"
                : "type, or press/hold right ⌥ to talk"
          }
          attachments={attachments}
          onAttach={attachImages}
          onRemoveAttachment={removeAttachment}
          onChange={(e) => setInputText(e.target.value)}
          onKeystroke={keystroke}
          onAbandon={abandonRecording}
          onAccept={acceptRecording}
          onSubmit={submit}
          inputRef={inputRef}
        />
        <VoiceNotice />
      </div>
    </div>
  );
});

import { useEffect, useRef } from "react";
import { placeSidePanels, pluginHost, useContributions } from "../plugins/host";
import { Rail } from "../plugins/Rail";
import { SettingsScreen } from "../settings/SettingsScreen";
import { HomeScreen } from "./HomeScreen";
import { useShellStore } from "./store";
import { TopBar } from "./TopBar";

export function App() {
  const theme = useShellStore((s) => s.theme);
  const view = useShellStore((s) => s.view);
  const setTheme = useShellStore((s) => s.setTheme);
  const setView = useShellStore((s) => s.setView);
  const init = useShellStore((s) => s.init);
  const backButtonRef = useRef<HTMLButtonElement>(null);
  const rails = placeSidePanels(useContributions(pluginHost.sidePanels));

  useEffect(() => {
    init();
  }, [init]);

  useEffect(() => {
    document.body.dataset.theme = theme;
  }, [theme]);

  // Hold-to-talk is focused-window only (decision D-10): plain renderer
  // keydown/keyup on right Alt while the app is focused - no global hooks,
  // no Input Monitoring permission, ever. Esc abandons.
  useEffect(() => {
    const down = (event: KeyboardEvent) => {
      const store = useShellStore.getState();
      if (event.key === "Escape") {
        if (store.phase === "recording") {
          store.abandonRecording();
        } else if (store.view === "settings") {
          store.setView("home");
        }
        return;
      }
      if (event.key === "Alt" && event.location === 2 && !event.repeat) {
        event.preventDefault();
        store.startRecording();
      }
    };
    const up = (event: KeyboardEvent) => {
      const store = useShellStore.getState();
      if (event.key === "Alt" && event.location === 2 && store.phase === "recording") {
        event.preventDefault();
        store.acceptRecording();
      }
    };
    window.addEventListener("keydown", down);
    window.addEventListener("keyup", up);
    return () => {
      window.removeEventListener("keydown", down);
      window.removeEventListener("keyup", up);
    };
  }, []);

  // Landing in settings moves focus to the back control so keyboard users
  // are not stranded in the previous screen's tree.
  useEffect(() => {
    if (view === "settings") {
      backButtonRef.current?.focus();
    }
  }, [view]);

  const home = view === "home";

  // The home shell (D5): two dock rails frame a STAGE that holds the fixed
  // geometry. An empty rail is zero-width (design/styles.css), so with both
  // empty the stage is the whole window and nothing below moves. The rails
  // are home-only in v1; Settings keeps its own centred composition. The
  // activity feed and the crew strip are panels on the left rail (phase 2,
  // the built-in plugin) - FYI lives in the feed (captain refinement 4a),
  // and the feed shows whenever it has lines, so an answered turn with zero
  // cards still leaves its trace there.
  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        background: "var(--bg-0)",
        overflow: "hidden",
        fontFamily: "var(--font-ui)",
      }}
    >
      <div style={{ position: "absolute", inset: 0, display: "flex", alignItems: "stretch" }}>
        {home && <Rail side="left" panels={rails.left} theme={theme} />}
        <div
          data-stage=""
          style={{
            position: "relative",
            flex: 1,
            minWidth: 0,
            // Stage-relative sizes (cqw) for anything that must not assume
            // the stage is the window.
            containerType: "inline-size",
          }}
        >
          {home && <HomeScreen />}
          {view === "settings" && <SettingsScreen />}
        </div>
        {home && <Rail side="right" panels={rails.right} theme={theme} />}
      </div>
      <TopBar
        view={view}
        theme={theme}
        onTheme={() => setTheme(theme === "dark" ? "light" : "dark")}
        onSettings={() => setView("settings")}
        onBack={() => setView("home")}
        backButtonRef={backButtonRef}
      />
    </div>
  );
}

