}

import { expect, type Page, test } from "@playwright/test";
import { type LaunchedApp, launchApp } from "./launch";
import { crewStrip, feedLine, nowRow } from "./rails";

/**
 * D5, the two side rails, against the built app (docs/ui-plugins.md). Since
 * phase 2 the left rail carries the app's own dogfood - the activity feed
 * and the crew strip as Tier-2 frames - and since task-system P4 the right
 * rail carries the now panel, so the six rules are proven on real
 * contributions: empty means zero width and nothing painted (the window is
 * pixel-identical to a tree with no rails at all), the first task opens
 * both rails to the one width token and insets the stage from both sides
 * without covering it, the chrome around each panel is the host's,
 * collapse is the host's, no resize affordance exists, and Settings renders
 * no rail. The mount cap is unit-tested (src/renderer/src/plugins/host.test.ts).
 */

type Geometry = {
  innerWidth: number;
  railWidthToken: string;
  rails: { side: string; width: number; children: number; padding: string; resize: string }[];
  panels: {
    id: string;
    size: string;
    collapsed: boolean;
    height: number;
    attributed: boolean;
    frame: { title: string; sandbox: string; src: string } | null;
  }[];
  stage: { x: number; width: number };
  characterCenter: number;
  inputCenter: number;
};

function geometry(page: Page): Promise<Geometry> {
  return page.evaluate(() => {
    const centerOf = (el: Element | null) => {
      const box = el?.getBoundingClientRect();
      return box ? box.x + box.width / 2 : Number.NaN;
    };
    const stage = document.querySelector("[data-stage]")?.getBoundingClientRect();
    return {
      innerWidth: window.innerWidth,
      railWidthToken: getComputedStyle(document.documentElement)
        .getPropertyValue("--rail-width")
        .trim(),
      rails: [...document.querySelectorAll("[data-rail]")].map((rail) => {
        const style = getComputedStyle(rail);
        return {
          side: rail.getAttribute("data-rail") ?? "",
          width: rail.getBoundingClientRect().width,
          children: rail.childElementCount,
          padding: style.padding,
          resize: style.resize,
        };
      }),
      panels: [...document.querySelectorAll("[data-side-panel]")].map((panel) => {
        const frame = panel.querySelector("iframe");
        return {
          id: panel.getAttribute("data-side-panel") ?? "",
          size: panel.getAttribute("data-side-panel-size") ?? "",
          collapsed: panel.hasAttribute("data-side-panel-collapsed"),
          height: panel.getBoundingClientRect().height,
          attributed: panel.querySelector("[data-side-panel-attribution]") !== null,
          frame: frame
            ? {
                title: frame.title,
                sandbox: frame.getAttribute("sandbox") ?? "",
                src: frame.getAttribute("src") ?? "",
              }
            : null,
        };
      }),
      stage: { x: stage?.x ?? Number.NaN, width: stage?.width ?? Number.NaN },
      characterCenter: centerOf(document.querySelector('[role="img"][aria-label^="Firstmate"]')),
      inputCenter: centerOf(document.querySelector("input")),
      debug: {
        railLeft: getComputedStyle(document.querySelector("[data-stage]") as Element).getPropertyValue(
          "--rail-left",
        ),
        mateLeft: getComputedStyle(
          document.querySelector('[role="img"][aria-label^="Firstmate"]')?.parentElement as Element,
        ).left,
      },
    };
  });
}

