}

/** Stage layer: cards and the screen label. Lives in the inset stage. */
export const HomeScreen = memo(function HomeScreen() {
  const phase = useShellStore((s) => s.phase);
  const inputText = useShellStore((s) => s.inputText);
  const showCards = phase === "working";
  const listening = phase === "recording" || inputText.length > 0;
  const screenLabel = showCards ? "Working" : listening ? "Listening" : "Null state";
  return (
    <div
      data-screen-label={screenLabel}
      style={{ position: "absolute", inset: 0, pointerEvents: showCards ? "auto" : "none" }}
    >
      {showCards && <CardLayer />}
    </div>
  );
});

/** Character, window-centred, painted behind the rails and cards. */
export const HomeMate = memo(function HomeMate() {
  const phase = useShellStore((s) => s.phase);
  const inputText = useShellStore((s) => s.inputText);
  const kick = useShellStore((s) => s.kick);
  const submitted = useShellStore((s) => s.submitted);
  const setInputText = useShellStore((s) => s.setInputText);
  const keystroke = useShellStore((s) => s.keystroke);
  const abandonRecording = useShellStore((s) => s.abandonRecording);
  const acceptRecording = useShellStore((s) => s.acceptRecording);
  const submit = useShellStore((s) => s.submit);
  const attachments = useShellStore((s) => s.attachments);
  const attachImages = useShellStore((s) => s.attachImages);
  const removeAttachment = useShellStore((s) => s.removeAttachment);
  const voiceSupported = useShellStore((s) => s.voiceSupported);
  const transcribing = useShellStore((s) => s.transcribing);
  const view = useShellStore((s) => s.view);
  const firstmateBusy = useShellStore((s) => s.firstmateBusy);
  const recording = phase === "recording";

  const focusRequest = useShellStore((s) => s.focusRequest);
  const inputRef = useRef<HTMLInputElement>(null);
  const focusHandled = useRef(0);
  useEffect(() => {
    // Each request is consumed exactly once, at the moment it fires: a
    // later view or recording change must not replay a stale focus steal
    // (e.g. refocusing the prompt on every return from Settings).
    if (focusRequest === focusHandled.current) return;
    focusHandled.current = focusRequest;
    if (view === "home" && !recording) {
      inputRef.current?.focus();
    }
  }, [focusRequest, view, recording]);

  const working = firstmateBusy;
  const showCards = phase === "working";
  const typing = inputText.length > 0;
  const listening = phase === "recording" || typing;

  return (
    <div style={{ position: "absolute", inset: 0, pointerEvents: "none" }}>
      {/* The Firstmate stays put in the back - cards float in front; when the
          stack empties he is revealed again. */}
      <div
        style={{
          position: "absolute",
          left: "50%",
          top: "calc(50% - 60px)",
          transform: "translate(-50%,-50%)",
          pointerEvents: "auto",
          opacity: showCards ? 0.45 : 1,
          filter: showCards ? "blur(3px)" : "none",
          transition:
            "opacity var(--dur-slow) var(--ease-out),filter var(--dur-slow) var(--ease-out)",
        }}
      >
        <Firstmate
          listening={listening}
          busy={working}
          size={300}
          kick={kick}
          submitSignal={submitted}
        />
      </div>
      <div
        style={{
          position: "absolute",
          left: "50%",
          // Anchored by the input's top (100% - 96px margin - 52px input), so
          // a voice notice growing underneath never shifts the input itself.
          top: "calc(100% - 148px)",
          transform: "translateX(-50%)",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          gap: 10,
          pointerEvents: "auto",
        }}
      >
        <VoiceInput
          mode={phase === "recording" ? "recording" : "idle"}
          width={STAGE_WIDTH}
          value={inputText}
          keybindHint={
            transcribing
              ? "transcribing what you said"
              : voiceSupported === false
                ? "type a task for a crewmate"
                : "type, or press/hold right ⌥ to talk"
          }
          attachments={attachments}
          onAttach={attachImages}
          onRemoveAttachment={removeAttachment}
          onChange={(e) => setInputText(e.target.value)}
          onKeystroke={keystroke}
          onAbandon={abandonRecording}
          onAccept={acceptRecording}
          onSubmit={submit}
          inputRef={inputRef}
        />
        <VoiceNotice />
      </div>
    </div>
  );
});

